<?php
declare(strict_types=1);

require __DIR__ . '/app/bootstrap.php';
require __DIR__ . '/app/admin_pages.php';

portal_enforce_https();
portal_enforce_canonical_application_path();
portal_send_security_headers();
$config = portal_config();
if (!$config['ready']) {
    http_response_code(503);
    portal_render_page('系統設定中', '<section class="panel narrow"><p class="eyebrow">PORTAL SETUP</p><h1>文件平台正在設定中</h1><p>SQLite 狀態、文件庫綁定或受保護工作階段設定尚未完成。</p></section>');
    exit;
}
try { portal_start_session($config); $database = portal_open_existing_state_database(); portal_state_verify_audit_chain($database); }
catch (Throwable $e) { error_log('TWWATER SQLite initialization failed: '.$e->getMessage()); http_response_code(503); portal_render_page('系統暫時無法使用','<section class="panel narrow"><h1>系統暫時無法使用</h1><p>請稍後再試，或聯絡系統管理者。</p></section>'); exit; }

$action = (string) ($_GET['action'] ?? 'documents');
$allowedActions = ['documents', 'login', 'google_login', 'google_callback', 'logout', 'view', 'download', 'inline', 'admin', 'admin_users', 'admin_library_health', 'admin_library_health_data', 'admin_audit', 'admin_account_create', 'admin_account_update', 'admin_account_confirm', 'admin_account_reset_password', 'change_password'];
if (!in_array($action, $allowedActions, true)) $action = 'documents';
try {
    if ($action === 'login') { portal_handle_login($database, $config); exit; }
    if ($action === 'google_login') { portal_handle_google_login($database, $config); exit; }
    if ($action === 'google_callback') { portal_handle_google_callback($database, $config); exit; }
    if ($action === 'logout') { portal_handle_logout($database); exit; }
    if ($action === 'change_password') { portal_handle_change_password($database); exit; }
    $user = portal_require_user($database);
    if ((int) ($user['must_change_password'] ?? 0) === 1) { header('Location: '.portal_url('change_password'), true, 303); exit; }
    if ($action === 'admin') { portal_render_admin_overview($user); exit; }
    if ($action === 'admin_users') { portal_render_admin_users_page(portal_require_admin($database), $database); exit; }
    if ($action === 'admin_library_health') { portal_render_admin_library_health_page(portal_require_admin($database)); exit; }
    if ($action === 'admin_library_health_data') { portal_handle_admin_library_health_data(portal_require_admin($database)); exit; }
    if ($action === 'admin_audit') { portal_render_admin_audit_page(portal_require_admin($database), $database); exit; }
    if ($action === 'admin_account_create') { portal_handle_admin_account_create($database, portal_require_admin($database)); exit; }
    if ($action === 'admin_account_update') { portal_handle_admin_account_update($database, portal_require_admin($database)); exit; }
    if ($action === 'admin_account_confirm') { portal_handle_admin_account_confirmation($database, portal_require_admin($database)); exit; }
    if ($action === 'admin_account_reset_password') { portal_handle_admin_account_reset_password($database, portal_require_admin($database)); exit; }
    if ($action === 'view') { portal_render_direct_document_page($config, $user, (string)($_GET['id'] ?? '')); exit; }
    if ($action === 'download' || $action === 'inline') { portal_handle_direct_file_response($config, $user, (string)($_GET['id'] ?? ''), $action === 'inline'); exit; }
    portal_render_document_library($config, $user);
} catch (Throwable $e) {
    error_log('TWWATER portal request failed: '.$e->getMessage()); http_response_code(400); portal_render_page('請求無法完成','<section class="panel narrow"><h1>請求無法完成</h1><p>請確認操作內容後再試一次。</p><a class="primary-button" href="'.portal_url('documents').'">返回文件庫</a></section>', $user ?? null);
}

function portal_handle_login(PDO $database, array $config): void
{
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        try { portal_assert_csrf(); $user = portal_sqlite_authenticate_local($database, (string)($_POST['username']??''), (string)($_POST['password']??'')); portal_complete_login_session($user); header('Location: '.portal_url('documents'),true,303); return; }
        catch (Throwable $e) { portal_render_page('系統登入','<section class="panel login-panel"><p class="eyebrow">SYSTEM LOGIN</p><h1>系統帳號登入</h1><p class="error-message">帳號、密碼或登入方式不正確。</p>'.portal_login_form($config,(string)($_POST['username']??'')).'</section>'); return; }
    }
    if(portal_current_user($database)!==null){header('Location: '.portal_url('documents'),true,303);return;}
    portal_render_page('系統登入','<section class="panel login-panel"><p class="eyebrow">SYSTEM LOGIN</p><h1>系統帳號登入</h1><p>請使用受授權的系統帳號登入。</p>'.portal_login_form($config).'</section>');
}
function portal_login_form(array $config,string $username=''): string { $form='<form method="post" action="'.portal_url('login').'" class="login-form" autocomplete="on">'.portal_csrf_field().'<label>帳號<input name="username" value="'.portal_e($username).'" maxlength="80" autocomplete="username" required autofocus></label><label>密碼<input name="password" type="password" autocomplete="current-password" required></label><button class="primary-button" type="submit">登入系統</button></form>'; return !$config['google_login_enabled']?$form:$form.'<div class="login-divider"><span>或</span></div><a class="google-login-button" href="'.portal_url('google_login').'">使用 Google 帳號驗證登入</a>'; }
function portal_handle_google_login(PDO $database, array $config): void { if(portal_current_user($database)!==null){header('Location: '.portal_url('documents'),true,303);return;}try{header('Location: '.portal_google_begin_authorization($config),true,302);}catch(Throwable){portal_render_page('Google 登入尚未啟用','<section class="panel narrow"><h1>Google 登入尚未啟用</h1><p>請先使用系統帳號登入，或聯絡管理員完成 Google Web OAuth 設定。</p><a class="primary-button" href="'.portal_url('login').'">返回登入頁</a></section>');} }
function portal_handle_google_callback(PDO $database, array $config): void { $pending=$_SESSION['google_oauth']??null;unset($_SESSION['google_oauth']);try{if(!is_array($pending)||time()-(int)($pending['created_at']??0)>600||!hash_equals((string)($pending['state']??''),(string)($_GET['state']??''))||isset($_GET['error']))throw new RuntimeException('Google 登入狀態已失效。');$identity=portal_google_exchange_code($config,(string)($_GET['code']??''),(string)($pending['verifier']??''),(string)($pending['nonce']??''));$user=portal_sqlite_authenticate_google($database,$identity['email'],$identity['subject']);portal_complete_login_session($user);header('Location: '.portal_url('documents'),true,303);}catch(Throwable $e){error_log('TWWATER Google login callback rejected: '.$e->getMessage());portal_render_page('Google 登入失敗','<section class="panel login-panel"><h1>Google 登入失敗</h1><p class="error-message">此 Google 帳號尚未由管理員綁定，或驗證已失效。</p>'.portal_login_form($config).'</section>');} }
function portal_handle_change_password(PDO $database): void { $user=portal_require_user($database);if($_SERVER['REQUEST_METHOD']==='POST'){try{portal_assert_csrf();$new=(string)($_POST['new_password']??'');if(!hash_equals($new,(string)($_POST['new_password_confirm']??'')))throw new RuntimeException('新密碼確認不一致。');portal_sqlite_change_password($database,(int)$user['user_id'],(string)($_POST['current_password']??''),$new);portal_flash_set('success','密碼已變更，請繼續使用系統。');header('Location: '.portal_url('documents'),true,303);return;}catch(Throwable){portal_render_page('變更密碼','<section class="panel login-panel"><h1>變更密碼</h1><p class="error-message">無法變更密碼；請確認目前密碼與新密碼長度。</p>'.portal_change_password_form().'</section>',$user);return;}}portal_render_page('變更密碼','<section class="panel login-panel"><h1>變更密碼</h1><p>此帳號必須先變更初始密碼，才能繼續使用。</p>'.portal_change_password_form().'</section>',$user); }
function portal_change_password_form():string{return '<form method="post" action="'.portal_url('change_password').'" class="login-form">'.portal_csrf_field().'<label>目前密碼<input name="current_password" type="password" autocomplete="current-password" required></label><label>新密碼（至少 16 字元）<input name="new_password" type="password" minlength="16" autocomplete="new-password" required></label><label>確認新密碼<input name="new_password_confirm" type="password" minlength="16" autocomplete="new-password" required></label><button class="primary-button" type="submit">確認變更密碼</button></form>';}
function portal_handle_logout(PDO $database): void { if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;} try{portal_assert_csrf();}catch(Throwable){if(portal_current_user($database)===null){portal_clear_session();header('Location: '.portal_url('login'),true,303);return;}portal_flash_set('error','登入狀態已更新，請再按一次登出。');header('Location: '.portal_url('documents'),true,303);return;} $u=portal_current_user($database);if($u!==null){$database->beginTransaction();try{portal_state_append_audit_event($database,(int)$u['user_id'],'logout',(int)$u['user_id'],[]);$database->commit();}catch(Throwable $e){if($database->inTransaction())$database->rollBack();throw $e;}}portal_clear_session();header('Location: '.portal_url('login'),true,303); }
function portal_render_document_library(array $config,array $user): void { $filters=['sort'=>(string)($_GET['sort']??'modified_desc')];$tree=portal_direct_library_folder_tree($config,$filters);$treeHtml=portal_render_explorer_tree_node($tree,'',true);$panels='';foreach($tree as $path=>$node){$folderRows='';foreach($node['folders'] as $child){$c=$tree[$child];$folderRows.='<tr class="explorer-folder-row"><td><button type="button" class="explorer-name-button" data-explorer-folder="'.portal_e(portal_direct_folder_id($child)).'">📁 '.portal_e((string)$c['name']).'</button></td><td>資料夾</td><td>'.number_format((int)$c['direct_count']).' 項</td><td>—</td></tr>';}$documentRows='';foreach($node['documents'] as $d)$documentRows.=portal_render_explorer_document_row($d);$panels.='<section class="explorer-content" data-explorer-content="'.portal_e(portal_direct_folder_id($path)).'"'.($path===''?'':' hidden').'>'.portal_render_explorer_breadcrumb($path).'<div class="table-scroll"><table class="explorer-table"><thead><tr><th>名稱</th><th>類型</th><th>修改時間</th><th>大小</th></tr></thead><tbody>'.($folderRows.$documentRows===''?'<tr><td colspan="4">這個資料夾沒有可顯示的資料夾或文件。</td></tr>':$folderRows.$documentRows).'</tbody></table></div></section>';}$content='<section class="hero"><p class="eyebrow">DOCUMENT LIBRARY</p><h1>文件庫</h1><p>以檔案總管方式瀏覽受保護文件庫；資料夾與文件皆為唯讀。</p></section><form method="get" class="library-filter panel" data-explorer-search-form><input type="hidden" name="action" value="documents"><label class="library-search-field">搜尋整個文件庫<input type="search" data-explorer-search name="q" maxlength="120" placeholder="檔名或相對路徑"></label><label>文件排序<select name="sort">'.portal_render_sort_options($filters['sort']).'</select></label><div class="filter-actions"><button class="primary-button">套用排序</button><button type="button" class="secondary-button" data-explorer-search-clear>清除搜尋</button></div></form><section class="explorer-shell"><aside class="explorer-sidebar panel"><details class="explorer-mobile-tree" open><summary>目錄樹</summary><div class="explorer-tree" data-explorer-tree>'.$treeHtml.'</div></details></aside><div class="explorer-main panel" data-explorer-main>'.$panels.'<section class="explorer-search-results" data-explorer-search-results hidden><div class="explorer-breadcrumb">搜尋結果</div><div class="table-scroll"><table class="explorer-table"><thead><tr><th>名稱</th><th>類型</th><th>相對路徑</th><th>修改時間</th><th>大小</th></tr></thead><tbody data-explorer-search-result-body></tbody></table></div></section></div></section>';portal_render_page('文件庫',$content,$user,false,'document-library-page'); }
function portal_render_explorer_breadcrumb(string $path):string{$segments=$path===''?[]:explode('/',$path);$parts=[['label'=>'文件庫','path'=>'']];$current='';foreach($segments as $segment){$current=$current===''?$segment:$current.'/'.$segment;$parts[]=['label'=>$segment,'path'=>$current];}$html='<nav class="explorer-breadcrumb" aria-label="目前資料夾路徑" data-explorer-breadcrumb>';foreach($parts as $index=>$part){if($index>0)$html.='<span class="explorer-breadcrumb-separator" aria-hidden="true">›</span>';$html.='<button type="button" class="explorer-breadcrumb-link" data-explorer-folder="'.portal_e(portal_direct_folder_id((string)$part['path'])).'"'.($index===count($parts)-1?' aria-current="page"':'').'>'.portal_e((string)$part['label']).'</button>';}$html.='</nav>';return $html;}
function portal_render_explorer_tree_node(array $tree,string $path,bool $root=false):string{$node=$tree[$path];$id=portal_direct_folder_id($path);$children='';foreach($node['folders'] as $child)$children.=portal_render_explorer_tree_node($tree,$child);$button='<button type="button" class="explorer-tree-button" data-explorer-folder="'.portal_e($id).'">'.($root?'📂 ':'📁 ').portal_e((string)$node['name']).'</button>';return $children===''?$button:'<details class="explorer-tree-node"'.($root?' open':'').'><summary>'.$button.'</summary><div class="explorer-tree-children">'.$children.'</div></details>';}
function portal_render_explorer_document_row(array $d):string{$id=(string)$d['public_id'];return '<tr class="explorer-document-row" data-explorer-document data-name="'.portal_e((string)$d['file_name']).'" data-path="'.portal_e((string)$d['relative_path']).'"><td><a href="'.portal_url('view',['id'=>$id]).'">📄 '.portal_e((string)$d['file_name']).'</a><span class="explorer-row-actions"><a href="'.portal_url('view',['id'=>$id]).'">開啟</a><a href="'.portal_url('download',['id'=>$id]).'">下載</a></span></td><td>'.portal_e(strtoupper((string)$d['extension'])).'</td><td>'.portal_e(portal_format_datetime((string)$d['source_modified_at'])).'</td><td>'.portal_e(portal_format_file_size((int)$d['file_size_bytes'])).'</td></tr>';}
function portal_render_sort_options(string $selected): string {$options=['modified_desc'=>'修改時間：新到舊','modified_asc'=>'修改時間：舊到新','name_asc'=>'名稱：昇冪','name_desc'=>'名稱：降冪'];$out='';foreach($options as $v=>$l)$out.='<option value="'.$v.'"'.($v===$selected?' selected':'').'>'.portal_e($l).'</option>';return $out;}
function portal_render_document_row(array $d): string {$id=(string)$d['public_id'];return '<article class="document-row"><div class="document-row-main"><h3><a href="'.portal_url('view',['id'=>$id]).'">'.portal_e((string)$d['title']).'</a></h3><p class="document-path">'.portal_e((string)$d['relative_path']).'</p><p class="document-subtitle">'.portal_e((string)$d['file_name']).' · '.portal_e(portal_format_file_size((int)$d['file_size_bytes'])).' · 修改：'.portal_e(portal_format_datetime((string)$d['source_modified_at'])).'</p></div><div class="document-row-actions"><a class="secondary-button compact-button" href="'.portal_url('view',['id'=>$id]).'">開啟</a><a class="secondary-button compact-button" href="'.portal_url('download',['id'=>$id]).'">下載</a></div></article>';}
function portal_handle_direct_file_response(array $config,array $user,string $id,bool $inline): void {$resolved=portal_direct_document_path($config,$id);if($resolved===null)throw new RuntimeException('找不到指定文件。');$d=$resolved['document'];$h=@fopen($resolved['path'],'rb');if(!is_resource($h)||!@flock($h,LOCK_SH))throw new RuntimeException('文件目前無法開啟。');$stat=fstat($h);if(!is_array($stat)||!isset($stat['size'])||(int)$stat['size']<0){flock($h,LOCK_UN);fclose($h);throw new RuntimeException('文件中繼資料無法驗證。');}$types=['pdf'=>'application/pdf','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','pptx'=>'application/vnd.openxmlformats-officedocument.presentationml.presentation','txt'=>'text/plain; charset=UTF-8'];header('Content-Type: '.($types[$d['extension']]??'application/octet-stream'));header('Content-Length: '.(string)$stat['size']);header('Content-Disposition: '.portal_document_content_disposition((string)$d['extension'],$inline).'; filename*=UTF-8\'\''.rawurlencode((string)$d['file_name']));header('X-Content-Type-Options: nosniff');fpassthru($h);flock($h,LOCK_UN);fclose($h);exit;}
function portal_render_direct_document_page(array $config,array $user,string $id): void {$resolved=portal_direct_document_path($config,$id);if($resolved===null)throw new RuntimeException('找不到指定文件。');$d=$resolved['document'];$content='<a class="back-link" href="'.portal_url('documents').'">← 返回文件庫</a><section class="panel"><h1>'.portal_e((string)$d['title']).'</h1><p class="document-path">'.portal_e((string)$d['relative_path']).'</p><p><a class="primary-button" href="'.portal_url('download',['id'=>$id]).'">下載文件</a>'.((string)$d['extension']==='pdf'?' <a class="secondary-button" href="'.portal_url('inline',['id'=>$id]).'">在瀏覽器開啟</a>':'').'</p></section>';portal_render_page('開啟文件',$content,$user);}
